import { useMemo, useState } from "react";
import { DecisionOptionCard, FieldFrame, PageHeader, Select, StatusPill, Typography } from "@autograph/components";
import { RecordDetailPanel } from "@autograph/compositions";

const exceptions = [
  {id:"ex-101",product:"Organic Whole Milk 1L",sku:"DRY-1048",location:"Downtown",severity:"Critical",onHand:3,reorderPoint:18,daysCover:0.6,supplier:"North Valley Dairy",leadTime:"2 days",packSize:12,suggested:36},
  {id:"ex-102",product:"Sparkling Water Lime 8pk",sku:"BEV-2281",location:"Downtown",severity:"Warning",onHand:9,reorderPoint:16,daysCover:2.1,supplier:"Clear Springs Co.",leadTime:"4 days",packSize:8,suggested:24},
  {id:"ex-103",product:"Free-range Eggs 12ct",sku:"DRY-1312",location:"Riverside",severity:"Critical",onHand:2,reorderPoint:14,daysCover:0.4,supplier:"Meadow Farm Foods",leadTime:"1 day",packSize:10,suggested:30},
  {id:"ex-104",product:"Sourdough Sandwich Loaf",sku:"BAK-0782",location:"Riverside",severity:"Warning",onHand:6,reorderPoint:12,daysCover:1.8,supplier:"City Bakehouse",leadTime:"1 day",packSize:6,suggested:18},
  {id:"ex-105",product:"Avocado Hass Each",sku:"PRD-0426",location:"Northside",severity:"Critical",onHand:5,reorderPoint:24,daysCover:0.8,supplier:"Pacific Produce",leadTime:"3 days",packSize:24,suggested:48},
  {id:"ex-106",product:"Greek Yogurt Plain 500g",sku:"DRY-1159",location:"Northside",severity:"Warning",onHand:7,reorderPoint:15,daysCover:2.3,supplier:"North Valley Dairy",leadTime:"2 days",packSize:6,suggested:18},
];

export default function StockExceptions() {
  const [location,setLocation] = useState("all");
  const [severity,setSeverity] = useState("all");
  const [selectedId,setSelectedId] = useState("ex-103");
  const [detailTab,setDetailTab] = useState("stock");
  const [replenished,setReplenished] = useState<string[]>([]);
  const visible = useMemo(() => exceptions.filter(item =>
    (location === "all" || item.location === location) &&
    (severity === "all" || item.severity === severity)).sort((a,b) => a.daysCover-b.daysCover), [location,severity]);
  const selected = visible.find(item => item.id === selectedId) ?? visible[0];
  const done = selected ? replenished.includes(selected.id) : false;
  const deliveryGap = selected ? Math.max(0, Number.parseFloat(selected.leadTime) - selected.daysCover) : 0;
  return <main className="min-h-screen bg-[var(--color-bg-page)] p-[var(--space-6)] text-[var(--color-text-primary)]">
    <div className="mx-auto grid max-w-[1440px] gap-[var(--space-5)]">
      <PageHeader title="Stock exceptions" subtitle={`${visible.length} ${visible.length === 1 ? "product needs" : "products need"} review · Lowest cover first · Select a product to review and replenish`} />
      <div className="grid gap-[var(--space-5)] md:grid-cols-2">
      <section aria-label="Exception filters" className="grid grid-cols-2 gap-[var(--space-4)]">
        <FieldFrame label="Location" htmlFor="location-filter"><Select id="location-filter" value={location} options={[{value:"all",label:"All locations"},{value:"Downtown",label:"Downtown"},{value:"Riverside",label:"Riverside"},{value:"Northside",label:"Northside"}]} onValueChange={setLocation} /></FieldFrame>
        <FieldFrame label="Severity" htmlFor="severity-filter"><Select id="severity-filter" value={severity} options={[{value:"all",label:"All severities"},{value:"Critical",label:"Critical"},{value:"Warning",label:"Warning"}]} onValueChange={setSeverity} /></FieldFrame>
      </section>
      </div>
      <div className="grid items-start gap-[var(--space-5)] md:grid-cols-2">
        <section aria-label="Product review list" className="grid gap-[var(--space-2)]">
        <div aria-label="Low-stock products" role="radiogroup" className="grid gap-[var(--space-3)]">
          {["Critical","Warning"].map(level => {
            const records = visible.filter(item => item.severity === level);
            return records.length ? <div key={level} role="group" aria-label={level} className="grid gap-[var(--space-3)]">
              <Typography as="h2" variant="body-strong">{level} · {records.length}</Typography>
              {records.map(item=><DecisionOptionCard key={item.id} name="stock-exception" value={item.id} title={item.product} description={`${item.location} · ${item.severity}`} tag={<Typography as="span" variant="body-strong">{item.daysCover}d cover</Typography>} selected={selected?.id===item.id} onSelect={()=>{setSelectedId(item.id);setDetailTab("stock");}} />)}
            </div> : null;
          })}
        </div>
        </section>
        <aside aria-label="Selected stock exception">
          {selected ? <RecordDetailPanel
            key={selected.id}
            title={selected.product}
            subtitle={<div className="grid gap-[var(--space-2)]"><Typography as="span" tone="secondary">{selected.sku} · {selected.location}</Typography><div className="flex flex-wrap items-center gap-[var(--space-3)]"><StatusPill label={selected.severity} tone="neutral" /><Typography as="span" tone="secondary">Preview only · No supplier contacted</Typography></div>{done ? <div role="status"><Typography variant="body-strong">Order simulated. Stock levels are unchanged.</Typography></div> : null}</div>}
            tabs={[{id:"stock",label:"Stock position"},{id:"supplier",label:"Supplier details"}]}
            activeTabId={detailTab}
            onTabChange={setDetailTab}
            sections={detailTab==="stock" ? [
              {id:"stock",title:"Replenishment summary",collapsible:false,items:[{type:"table",id:"stock-metrics",ariaLabel:"Stock metrics",density:"compact",columns:[{id:"metric",label:"Metric"},{id:"value",label:"Current",align:"right"}],rows:[{metric:"Estimated cover",value:`${selected.daysCover} days`},{metric:"On hand",value:`${selected.onHand} units`},{metric:"Reorder point",value:`${selected.reorderPoint} units`},{metric:"Suggested order",value:`${selected.suggested} units`}]}]},
            ] : [
              {id:"supplier",title:"Ordering details",collapsible:false,items:[{type:"table",id:"supplier-details",ariaLabel:"Supplier ordering details",density:"compact",columns:[{id:"detail",label:"Detail"},{id:"value",label:"Terms",align:"right"}],rows:[{detail:"Supplier",value:selected.supplier},{detail:"Lead time",value:selected.leadTime},{detail:"Order pack",value:`${selected.packSize} units`}]},{type:"note",id:"delivery-context",title:deliveryGap>0?`Delivery gap: ${deliveryGap.toFixed(1)} days`:"Standard delivery fits current cover",body:deliveryGap>0?"Confirm faster delivery before ordering.":"Confirm demand and supplier availability.",tone:deliveryGap>0?"warning":"neutral"}]},
            ]}
            actions={[{id:"replenish",label:done?"Simulated — no order sent":`Simulate ${selected.suggested}-unit order`,intent:"primary",disabled:done}]}
            onAction={()=>setReplenished(current=>[...current,selected.id])}
          /> : <RecordDetailPanel title="No products to review" subtitle="Try a different location or severity." sections={[]} />}
        </aside>
      </div>
    </div>
  </main>;
}
